1	use crate::types::{ExtendedPatchInfo, PatchGroupRecord};
2	use derive_more::{Display, Error};
3	use miette::Diagnostic;
4	use node_semver::{Range, Version};
5	
6	/// Raised when a `name@version` pair satisfies more than one
7	/// configured version range. The user must add an exact-version
8	/// entry to break the tie.
9	///
10	/// Mirrors upstream's
11	/// [`ERR_PNPM_PATCH_KEY_CONFLICT`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/getPatchInfo.ts#L5-L19).
12	#[derive(Debug, Display, Error, Diagnostic)]
13	#[display(
14	    "Unable to choose between {n_satisfied} version ranges to patch {pkg_name}@{pkg_version}: {ranges}",
15	    n_satisfied = satisfied_versions.len(),
16	    ranges = satisfied_versions.join(", "),
17	)]
18	#[diagnostic(
19	    code(ERR_PNPM_PATCH_KEY_CONFLICT),
20	    help("Explicitly set the exact version ({pkg_name}@{pkg_version}) to resolve conflict")
21	)]
22	pub struct PatchKeyConflictError {
23	    pub pkg_name: String,
24	    pub pkg_version: String,
25	    pub satisfied_versions: Vec<String>,
26	}
27	
28	/// Look up the patch (if any) that applies to `pkg_name@pkg_version`.
29	///
30	/// Ports upstream's
31	/// [`getPatchInfo`](https://github.com/pnpm/pnpm/blob/b4f8f47ac2/patching/config/src/getPatchInfo.ts#L21-L40).
32	/// Match precedence:
33	///
34	/// 1. exact version (`exact[pkg_version]`)
35	/// 2. unique satisfying range (error if more than one)
36	/// 3. wildcard (`all`)
37	///
38	/// Returns `Ok(None)` when nothing matches the name *or* when the
39	/// name matches but every bucket misses. Returns `Err(...)` only on
40	/// rule 2's ambiguity.
41	///
42	/// If the configured ranges fail to parse as semver, those entries
43	/// are silently skipped — the upstream JS path goes through
44	/// `semver.satisfies`, which treats unparsable ranges as
45	/// non-matching. Pacquet matches that behavior.
46	pub fn get_patch_info<'a>(
47	    patch_file_groups: Option<&'a PatchGroupRecord>,
48	    pkg_name: &str,
49	    pkg_version: &str,
50	) -> Result<Option<&'a ExtendedPatchInfo>, PatchKeyConflictError> {
51	    let Some(groups) = patch_file_groups else {
52	        return Ok(None);
53	    };
54	    let Some(group) = groups.get(pkg_name) else {
55	        return Ok(None);
56	    };
57	
58	    if let Some(exact) = group.exact.get(pkg_version) {
59	        return Ok(Some(exact));
60	    }
61	
62	    let Ok(parsed_version) = Version::parse(pkg_version) else {
63	        // Non-semver target version: only exact-string and wildcard
64	        // can match. `pkg_version` already missed the exact bucket
65	        // above, so fall through to `all`.
66	        return Ok(group.all.as_ref());
67	    };
68	
69	    let satisfied: Vec<&'a crate::types::PatchGroupRangeItem> = group
70	        .range
71	        .iter()
72	        .filter(|item| match Range::parse(&item.version) {
73	            Ok(range) => range.satisfies(&parsed_version),
74	            Err(_) => false,
75	        })
76	        .collect();
77	
78	    if satisfied.len() > 1 {
79	        return Err(PatchKeyConflictError {
80	            pkg_name: pkg_name.to_string(),
81	            pkg_version: pkg_version.to_string(),
82	            satisfied_versions: satisfied.iter().map(|item| item.version.clone()).collect(),
83	        });
84	    }
85	    if let [only] = satisfied.as_slice() {
86	        return Ok(Some(&only.patch));
87	    }
88	
89	    Ok(group.all.as_ref())
90	}
91	
92	#[cfg(test)]
93	mod tests;
