7	/// Syntax: `{name}@{suffix}`
8	///
9	/// Examples:
10	/// * `ts-node@10.9.1`, `@types/node@18.7.19`, `typescript@5.1.6`
11	/// * `react-json-view@1.21.3(@types/react@17.0.49)(react-dom@17.0.2)(react@17.0.2)`
12	#[derive(Debug, Display, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
13	#[display(bound(Suffix: std::fmt::Display))]
14	#[display("{name}@{suffix}")]
15	#[serde(try_from = "Cow<'de, str>", into = "String")]
16	#[serde(bound(
17	    deserialize = "Suffix: FromStr, Suffix::Err: std::fmt::Display",
18	    serialize = "Suffix: std::fmt::Display + Clone",
19	))]
20	pub struct PkgNameSuffix<Suffix> {
21	    pub name: PkgName,
22	    pub suffix: Suffix,
23	}
24	
25	impl<Suffix> PkgNameSuffix<Suffix> {
26	    /// Construct a [`PkgNameSuffix`].
27	    pub fn new(name: PkgName, suffix: Suffix) -> Self {
28	        PkgNameSuffix { name, suffix }
29	    }
30	}
