32	/// Error when parsing [`PkgNameSuffix`] from a string.
33	#[derive(Debug, Display, Error)]
34	#[display(bound(ParseSuffixError: Display))]
35	pub enum ParsePkgNameSuffixError<ParseSuffixError> {
36	    #[display("Input is empty")]
37	    EmptyInput,
38	    #[display("Suffix is missing")]
39	    MissingSuffix,
40	    #[display("Name is empty")]
41	    EmptyName,
42	    #[display("Failed to parse suffix: {_0}")]
43	    ParseSuffixFailure(#[error(source)] ParseSuffixError),
44	    #[display("Failed to parse name: {_0}")]
45	    ParseNameFailure(#[error(source)] ParsePkgNameError),
46	}
47	
48	impl<Suffix: FromStr> FromStr for PkgNameSuffix<Suffix> {
