+/// Compute the `pkgIdWithPatchHash` for a resolved package: the
+/// resolver's `id`, suffixed with `(patch_hash=<hash>)` when
+/// `ctx.patched_dependencies` carries a patch matching the package's
+/// name and version. The matched configured key is recorded in
+/// `ctx.applied_patches`.
+///
+/// Matching needs the resolution-time `name@version`, so resolvers that
+/// leave [`ResolveResult::name_ver`] `None` (git / tarball / local) are
+/// never patched — same as upstream, where `patchedDependencies` keys
+/// are matched against the package name. Returns
+/// [`ResolveDependencyTreeError::PatchKeyConflict`] when more than one
+/// range entry satisfies the version.
+async fn apply_patch_hash(
+    ctx: &TreeCtx,
+    result: &pacquet_resolving_resolver_base::ResolveResult,
+) -> Result<String, ResolveDependencyTreeError> {
+    let id = result.id.to_string();
+    let Some(patches) = ctx.patched_dependencies.as_deref() else {
+        return Ok(id);
+    };
+    let Some(name_ver) = result.name_ver.as_ref() else {
+        return Ok(id);
+    };
+    let name = name_ver.name.to_string();
+    let version = name_ver.suffix.to_string();
+    match get_patch_info(Some(patches), &name, &version)
+        .map_err(ResolveDependencyTreeError::PatchKeyConflict)?
+    {
+        Some(patch) => {
+            ctx.applied_patches.lock().await.insert(patch.key.clone());
+            Ok(format!("{id}(patch_hash={})", patch.hash))
+        }
+        None => Ok(id),
+    }
+}
